class SSPPostMatric {

    static void createAccount(long aadhaarNumber, int otp,
                              String studentName, String fatherName,
                              String gender, String dateOfBirth,
                              long mobileNumber, String email,
                              String course, String collegeName,
                              String bankName, String ifsc,
                              String password) {

        System.out.println("SSP Post-Matric Scholarship Account Creation");
        System.out.println("Aadhaar Number : " + aadhaarNumber);
        System.out.println("OTP            : " + otp);
        System.out.println("Student Name   : " + studentName);
        System.out.println("Father Name    : " + fatherName);
        System.out.println("Gender         : " + gender);
        System.out.println("Date of Birth  : " + dateOfBirth);
        System.out.println("Mobile Number  : " + mobileNumber);
        System.out.println("Email ID       : " + email);
        System.out.println("Course         : " + course);
        System.out.println("College Name   : " + collegeName);
        System.out.println("Bank Name      : " + bankName);
        System.out.println("IFSC Code      : " + ifsc);
        System.out.println("Password       : " + password);
    }
}
